import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_BARE_INT_RE = re.compile(r'^\d+$')

_ISO_RE = re.compile(
    r'^P(?:(?P<weeks>\d+(?:\.\d+)?)W)?'
    r'(?:(?P<days>\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(?P<hours>\d+(?:\.\d+)?)H)?'
    r'(?:(?P<minutes>\d+(?:\.\d+)?)M)?'
    r'(?:(?P<seconds>\d+(?:\.\d+)?)S)?)?$'
)

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration cannot be None")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty duration")

    # Bare non-negative integer
    if _BARE_INT_RE.match(stripped):
        return int(stripped)

    # ISO 8601 duration
    if stripped[0] == 'P':
        match = _ISO_RE.match(stripped)
        if match and any(match.groupdict().values()):
            total = 0.0
            for name, value in match.groupdict().items():
                if value:
                    unit = {
                        'weeks': 604800,
                        'days': 86400,
                        'hours': 3600,
                        'minutes': 60,
                        'seconds': 1,
                    }[name]
                    total += float(value) * unit
            return round(total)
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    # Clock notation hh:mm:ss or mm:ss
    if ':' in stripped:
        parts = stripped.split(':')
        if len(parts) in (2, 3) and all(re.match(r'^\d+(?:\.\d+)?$', p) for p in parts):
            weights = [3600, 60, 1] if len(parts) == 3 else [60, 1]
            total = sum(float(p) * w for p, w in zip(parts, weights))
            return round(total)
        raise ValueError(f"invalid clock duration: {text!r}")

    # Number+unit components, optionally space separated
    no_space = stripped.replace(' ', '')
    matches = list(_COMPONENT_RE.finditer(stripped))
    if not matches:
        raise ValueError(f"invalid duration: {text!r}")

    consumed = ''.join(m.group(0) for m in matches)
    consumed_no_space = consumed.replace(' ', '')
    if consumed_no_space != no_space:
        raise ValueError(f"invalid duration: {text!r}")

    total = 0.0
    for m in matches:
        number_str, unit_str = m.group(1), m.group(2)
        unit = unit_str.lower()
        if unit not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit_str!r}")
        total += float(number_str) * _UNIT_SECONDS[unit]

    return round(total)

